<script>document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('home-room-calendar'),cal=document.getElementById('home-calendar'),days=document.getElementById('home-days'),month=document.getElementById('home-month'),list=document.getElementById('home-booked-list'),today=new Date();today.setHours(0,0,0,0);let cursor=new Date(today.getFullYear(),today.getMonth(),1),ranges=[];const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,occupied=v=>ranges.some(r=>v>=r.start&&v<r.end),pretty=v=>new Date(`${v}T00:00:00`).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});const render=()=>{days.innerHTML='';month.textContent=cursor.toLocaleDateString('en-PH',{month:'long',year:'numeric'});const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),last=new Date(cursor.getFullYear(),cursor.getMonth()+1,0);for(let i=0;i<first.getDay();i++)days.insertAdjacentHTML('beforeend','<span class="home-blank"></span>');for(let n=1;n<=last.getDate();n++){const d=new Date(cursor.getFullYear(),cursor.getMonth(),n),v=iso(d),booked=occupied(v),p=new Date(d),next=new Date(d);p.setDate(p.getDate()-1);next.setDate(next.getDate()+1);const c=booked?` booked${occupied(iso(p))?'':' booked-start'}${occupied(iso(next))?'':' booked-end'}`:'';days.insertAdjacentHTML('beforeend',`<span class="home-day${c}">${n}</span>`)}list.innerHTML=ranges.length?ranges.map(r=>{const nights=Math.round((new Date(`${r.end}T00:00:00`)-new Date(`${r.start}T00:00:00`))/86400000);return `<span>Booked: ${pretty(r.start)} to ${pretty(r.end)} · ${nights} night${nights===1?'':'s'}</span>`}).join(''):'<span>No booked dates recorded for this room.</span>'};const load=async()=>{const url=select.selectedOptions[0]?.dataset.url;if(!url){cal.hidden=true;return}const res=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});ranges=(await res.json()).ranges;cal.hidden=false;render()};select.addEventListener('change',load);document.getElementById('home-prev').onclick=()=>{cursor=new Date(cursor.getFullYear(),cursor.getMonth()-1,1);render()};document.getElementById('home-next').onclick=()=>{cursor=new Date(cursor.getFullYear(),cursor.getMonth()+1,1);render()}});</script>
